from pathlib import Path
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download';src=(r/'docs/replica/source/original.js').read_text().splitlines()
defs='\n'.join(x for x in src if x.startswith(('const initial=','let state=','const esc=','const icons=','const icon=','const t=','const btn=','const pill=','const notice=','const heading=','const categoryDefs=','function capabilities(')))
script=defs+'''
const cases=[];for(const language of ['ko','en'])for(const width of [478,610,656,858,904,1118]){lang=language;const f=document.createElement('div');f.className='fixture';f.style.width=(width+2)+'px';f.innerHTML=capabilities();f.querySelectorAll('.page-heading,.notice,.section').forEach(x=>x.remove());document.getElementById('fixtures').append(f);f.dataset.id=language+'-'+width;const row=f.querySelector('thead tr');cases.push({id:f.dataset.id,english:language==='en',columns:[...row.cells].map(c=>c.getBoundingClientRect().width)})}
function read(){return [...document.querySelectorAll('.fixture')].map(f=>{const row=f.querySelector('thead tr'),r=row.getBoundingClientRect(),box=q=>({x:q.x-r.x,y:q.y-r.y,width:q.width,height:q.height});return{id:f.dataset.id,root:box(r),cells:[...row.cells].map(c=>{const q=c.getBoundingClientRect(),s=getComputedStyle(c),range=document.createRange();range.selectNodeContents(c);return{box:box(q),text:c.textContent,textBox:box(range.getBoundingClientRect()),lineRects:[...range.getClientRects()].map(box),font:s.fontFamily,fontSize:s.fontSize,fontWeight:s.fontWeight,lineHeight:s.lineHeight,color:s.color,background:s.backgroundColor,textAlign:s.textAlign,padding:s.padding,border:s.borderBottom,verticalAlign:s.verticalAlign}})}})}
document.getElementById('capabilityheader-record').onclick=async()=>{await document.fonts.ready;const res=await fetch('/evidence/preflight-capabilityheader-'+(new URLSearchParams(location.search).get('os')==='mac'?'mac':'windows')+'-source.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,headers:read(),cases})});if(!res.ok)throw Error('Record failed');document.getElementById('capabilityheader-record').textContent='Capability headers recorded'};
'''
(o/'capabilityheader-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes());(o/'capabilityheader.html').write_text('<!doctype html><meta charset="utf-8"><title>CapabilityHeader · original isolation</title><link rel="stylesheet" href="capabilityheader-original.css"><style>.fixture{position:absolute;left:30px;top:40px}.fixture:not(:first-child){visibility:hidden}.fixture *{animation:none!important;transition:none!important}</style><div id="fixtures"></div><button id="capabilityheader-record" style="position:fixed;right:20px;top:20px">Record CapabilityHeader</button><script>'+script+'</script>');print('12 actual-table header fixtures prepared')
